steps.script:
var n = tree.root.get_node_or_null("MainMenu/TutorialNudge")
if n != null and n.visible:
	n._mark_seen()
return true

var row = tree.root.get_node("MainMenu/TutorialPicker/Margin/VBox/LessonRows/Row_t1_basics")
var found = false
var q = [row]
while not q.is_empty():
	var n = q.pop_back()
	if n is Label and str(n.text) == "Scouting the Field":
		found = true
	for c in n.get_children():
		q.append(c)
return found
